import pandas as pd
from fractions import Fraction


# Load the datasets
all_drinks_df = pd.read_csv('opensource/tidytuesday/2020-05-26/Data/all_drinks.csv')
boston_cocktails_df = pd.read_csv('opensource/tidytuesday/2020-05-26/Data/boston_cocktails.csv')

# Function to convert measurements to ounces
def convert_to_oz(measure):
    if pd.isnull(measure):
        return 0
    measure = measure.strip().lower()
    try:
        if 'oz' in measure:
            return float(sum(Fraction(s) for s in measure.replace('oz', '').strip().split()))
        elif 'shot' in measure:
            return float(sum(Fraction(s) for s in measure.replace('shot', '').strip().split())) * 1.5  # Assuming a shot is 1.5 oz
        elif 'ml' in measure:
            return float(sum(Fraction(s) for s in measure.replace('ml', '').strip().split())) * 0.033814  # 1 ml is 0.033814 oz
        elif 'cl' in measure:
            return float(sum(Fraction(s) for s in measure.replace('cl', '').strip().split())) * 0.33814  # 1 cl is 0.33814 oz
        elif 'cup' in measure:
            return float(sum(Fraction(s) for s in measure.replace('cup', '').strip().split())) * 8  # Assuming 1 cup is 8 oz
        # Add more conversion rules if needed
        return float(sum(Fraction(s) for s in measure.split()))
    except (ValueError, ZeroDivisionError):
        return 0

# Extract relevant columns for analysis
tequila_ingredients = ['Tequila']
lime_ingredients = ['Lime Juice']

def get_tequila_and_lime_ratio_all_drinks(row):
    tequila_amount = 0
    lime_amount = 0

    for i in range(1, 16):
        if row[f'strIngredient{i}'] in tequila_ingredients:
            tequila_amount += convert_to_oz(row[f'strMeasure{i}'])
        elif row[f'strIngredient{i}'] in lime_ingredients:
            lime_amount += convert_to_oz(row[f'strMeasure{i}'])

    if lime_amount == 0:
        return None
    return tequila_amount / lime_amount

# Find margarita recipes
margarita_all_drinks = all_drinks_df[all_drinks_df['strDrink'].str.contains('Margarita', case=False, na=False)]
margarita_boston_cocktails = boston_cocktails_df[boston_cocktails_df['name'].str.contains('Margarita', case=False, na=False)]

# Compute the ratios for 'all_drinks'
ratios_all_drinks = margarita_all_drinks.apply(get_tequila_and_lime_ratio_all_drinks, axis=1)
ratios_all_drinks = ratios_all_drinks.dropna().tolist()

# Compute the ratios for 'boston_cocktails'
boston_ratios = []
for name, group in margarita_boston_cocktails.groupby('name'):
    tequila_amount = group[group['ingredient'].str.contains('Tequila', case=False)]['measure'].apply(convert_to_oz).sum()
    lime_amount = group[group['ingredient'].str.contains('Lime Juice', case=False)]['measure'].apply(convert_to_oz).sum()
    if lime_amount > 0:
        boston_ratios.append(tequila_amount / lime_amount)

# Combine both ratios list
combined_ratios = ratios_all_drinks + boston_ratios

# Calculate average ratio
average_ratio = sum(combined_ratios) / len(combined_ratios) if combined_ratios else 0

print(f"Average ratio of tequila to lime juice in margarita recipes: {average_ratio:.2f}")

